mod private_publication_group {
    use super::*;
    use semio_framework_value::{ValueError, retained_clone::{RetainedCloneGrant, RetainedCloneStep}};
    use std::{mem::ManuallyDrop, sync::Arc};

    mod child { include!("🪆️child/🦀️.rs"); }
    pub(crate) use child::{PrivateChildPublicationInput, PrivateChildPublicationInputParts};
    mod owner { include!("📦️owner/🦀️.rs"); }
    pub(crate) use owner::{PrivateChildGroupSource, PrivateChildPublicationGroup, PrivateChildPreparedReceipt, PRIVATE_CHILD_GROUP_MAXIMUM_CHILDREN};

    #[derive(Clone, Copy, PartialEq, Eq)]
    enum PrivateOwnedPublicationPhase { Admission, Preparation, Staging, Staged, Adopted, Closing, Complete }

    pub(crate) struct PrivateOwnedPublicationLane {
        request: ManuallyDrop<Option<store::MemberStoreOwnedBatchRequest>>,
        publication: ManuallyDrop<Option<Box<dyn store::ErasedMemberStoreOneItemPublication>>>,
        metadata: Option<PrivatePublicationMetadata>,
        phase: PrivateOwnedPublicationPhase,
        grouped: bool,
    }

    impl PrivateOwnedPublicationLane {
        /// 🪪️ Retains one original typed source and its independently admitted metadata.
        pub(crate) fn new(request: store::MemberStoreOwnedBatchRequest) -> Self { Self { request: ManuallyDrop::new(Some(request)), publication: ManuallyDrop::new(None), metadata: None, phase: PrivateOwnedPublicationPhase::Admission, grouped: false } }
        pub(crate) fn request(&self) -> Option<&store::MemberStoreOwnedBatchRequest> { self.request.as_ref() }
        pub(crate) fn publication_mut(&mut self) -> Option<&mut (dyn store::ErasedMemberStoreOneItemPublication + 'static)> { self.publication.as_deref_mut() }
        pub(crate) fn staged(&self) -> bool { self.phase == PrivateOwnedPublicationPhase::Staged }
        pub(crate) fn prepared_for_staging(&self) -> bool { self.phase == PrivateOwnedPublicationPhase::Staging }
        pub(crate) fn prepared_edit_id(&self) -> Option<&str> { self.prepared_for_staging().then(|| self.publication.as_ref()?.prepared_edit_id()).flatten() }
        pub(crate) fn prepared_publication(&self) -> Option<&dyn store::ErasedMemberStoreOneItemPublication> { if self.prepared_for_staging() { self.publication.as_deref() } else { None } }
        pub(crate) fn adopted(&self) -> bool { self.phase == PrivateOwnedPublicationPhase::Adopted }
        pub(crate) fn progress(&self) -> store::ArtifactStoreOneItemCheckpoint { self.publication.as_ref().map_or(Default::default(), |publication| publication.progress()) }
        /// 🎟️ Borrows the complete constructor extent before any typed source handoff.
        pub(crate) fn next_capacity_byte_demand(&self, member: &impl SpaceMember) -> Result<usize, String> {
            if self.phase == PrivateOwnedPublicationPhase::Admission { return member.owned_publication_birth_bytes(self.request.as_ref().expect("private admission retains its original request")); }
            Ok(self.publication.as_ref().map_or(0, |publication| publication.next_group_byte_demand()))
        }
        /// 🪜️ Advances only one retained lane phase; staging never changes live authority.
        pub(crate) fn advance(&mut self, member: &mut impl SpaceMember, visibility: &Arc<vcs::ArtifactGroupVisibility>, grant: store::ArtifactStoreOneItemGrant) -> Result<store::ArtifactStoreOneItemPreparationStep, String> {
            if grant.maximum_items == 0 { return Ok(store::ArtifactStoreOneItemPreparationStep::Blocked); }
            match self.phase {
                PrivateOwnedPublicationPhase::Admission => {
                    let Some(publication) = member.begin_one_item_owned_publication(self.request.as_mut().expect("private source retained until admission"), grant)? else { return Ok(store::ArtifactStoreOneItemPreparationStep::Blocked); };
                    *self.publication = Some(publication);
                    self.phase = PrivateOwnedPublicationPhase::Preparation;
                    Ok(store::ArtifactStoreOneItemPreparationStep::Progress(self.progress()))
                }
                PrivateOwnedPublicationPhase::Preparation => {
                    let step = member.prepare_one_item_publication(self.publication_mut().unwrap(), grant)?;
                    if matches!(step, store::ArtifactStoreOneItemPreparationStep::Prepared(_)) { self.phase = PrivateOwnedPublicationPhase::Staging; return Ok(store::ArtifactStoreOneItemPreparationStep::Progress(self.progress())); }
                    Ok(step)
                }
                PrivateOwnedPublicationPhase::Staging => {
                    self.grouped = true;
                    let step = member.stage_one_item_publication(self.publication_mut().unwrap(), visibility, grant)?;
                    if matches!(step, store::ArtifactStoreOneItemPreparationStep::Prepared(_)) { self.phase = PrivateOwnedPublicationPhase::Staged; }
                    Ok(if self.staged() { store::ArtifactStoreOneItemPreparationStep::Prepared(self.progress()) } else { step })
                }
                PrivateOwnedPublicationPhase::Staged => Ok(store::ArtifactStoreOneItemPreparationStep::Prepared(self.progress())),
                _ => Err("private publication preparation requires its original pending lane".into()),
            }
        }
        /// 🔓️ Adopts the already staged root only after the exact common visibility commits.
        pub(crate) fn adopt(&mut self, member: &mut impl SpaceMember, visibility: &Arc<vcs::ArtifactGroupVisibility>, grant: store::ArtifactStoreOneItemGrant) -> Result<store::ArtifactStoreOneItemPreparationStep, String> {
            if self.adopted() { return Ok(store::ArtifactStoreOneItemPreparationStep::Prepared(self.progress())); }
            if !self.staged() { return Err("private publication adoption requires its fully staged candidate".into()); }
            let step = member.adopt_one_item_publication(self.publication_mut().unwrap(), visibility, grant)?;
            if matches!(step, store::ArtifactStoreOneItemPreparationStep::Prepared(_)) { self.phase = PrivateOwnedPublicationPhase::Adopted; self.grouped = false; }
            Ok(step)
        }
        /// 📐️ Exposes one indivisible active source, staged root, metadata, or frame demand.
        pub(crate) fn next_close_byte_demand(&self) -> Result<usize, ValueError> {
            if let Some(publication) = self.publication.as_ref() {
                if publication.terminal_is_empty() { return Ok(std::mem::size_of_val(publication.as_ref())); }
                return Ok(if self.grouped && publication.phase() != store::ArtifactStoreOneItemPublicationPhase::Closing { publication.next_group_byte_demand().max(4096) } else { publication.next_close_byte_demand() });
            }
            if let Some(request) = self.request.as_ref() { let (capacity, release) = request.mutations.next_demands()?; return Ok(capacity.max(release).max(request.mutations.next_copy_byte_demand())); }
            Ok(self.metadata.as_ref().map_or(0, PrivatePublicationMetadata::next_close_byte_demand))
        }
        /// ♻️ Returns staged authority before retiring original sources and whole physical frames.
        pub(crate) fn close_step(&mut self, member: &mut impl SpaceMember, grant: store::ArtifactStoreOneItemGrant) -> Result<PluginCloseStep, ValueError> {
            if self.terminal_is_empty() { return Ok(PluginCloseStep::Complete); }
            if grant.maximum_items == 0 { return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }); }
            self.phase = PrivateOwnedPublicationPhase::Closing;
            if let Some(publication) = self.publication.as_mut() {
                if !publication.terminal_is_empty() {
                    return member.abort_one_item_publication(publication.as_mut(), grant).map(|step| match step { store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes }, store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "private publication retains its exact source or staged snapshot reader" }, store::SnapshotRetirementStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 } });
                }
                let bytes = std::mem::size_of_val(publication.as_ref());
                if grant.maximum_bytes < bytes { return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 }); }
                self.publication.take();
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
            }
            let controlled = RetainedCloneGrant { maximum_items: 1, maximum_copy_bytes: grant.maximum_bytes.min(64), maximum_capacity_bytes: grant.maximum_bytes, maximum_release_bytes: grant.maximum_bytes, maximum_depth: 64 };
            if let Some(request) = self.request.as_mut() {
                if !request.mutations.terminal_is_empty() { return request.mutations.close_granted(controlled).map(Self::close_progress); }
                let request = self.request.take().unwrap();
                self.metadata = Some(PrivatePublicationMetadata::from_parts(PrivatePublicationMetadataParts { actor: request.actor, transaction: request.transaction, group_id: request.group_id }));
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(metadata) = self.metadata.as_mut() {
                let step = metadata.close_granted(controlled)?;
                if metadata.terminal_is_empty() { self.metadata = None; }
                return Ok(Self::close_progress(step));
            }
            self.phase = PrivateOwnedPublicationPhase::Complete;
            Ok(PluginCloseStep::Complete)
        }
        fn close_progress(step: RetainedCloneStep) -> PluginCloseStep { let progress = step.progress(); PluginCloseStep::Pending { released_items: progress.copied_items, released_bytes: progress.released_bytes } }
        pub(crate) fn terminal_is_empty(&self) -> bool { self.phase == PrivateOwnedPublicationPhase::Complete && self.request.is_none() && self.publication.is_none() && self.metadata.is_none() }
    }

    impl Drop for PrivateOwnedPublicationLane { fn drop(&mut self) { assert!(std::thread::panicking() || self.terminal_is_empty(), "private typed publication retains its original source and staged authority until bounded terminal close"); } }
}

pub(crate) use private_publication_group::{PrivateOwnedPublicationLane, PrivateChildPublicationInput, PrivateChildPublicationInputParts, PrivateChildGroupSource, PrivateChildPublicationGroup, PrivateChildPreparedReceipt, PRIVATE_CHILD_GROUP_MAXIMUM_CHILDREN};

use mounted_child_group_receipt_group::{MountedGroupMemberReceipts,MountedCommandEntry,MountedCommandEntrySource,MountedGroupReceiptOutput};
use mounted_child_group_receipt::MountedArtifactHandleIssuer;
use std::mem::ManuallyDrop;

struct MountedPrivateChildGroup<M:SpaceMember+MemberFactory> {
    identity:MountedChildGroupIdentityIssuer,
    parent_issuer:MountedArtifactHandleIssuer,
    parent_issuer_closed:bool,
    parent_handle:Option<ArtifactHandle>,
    parent_touched:bool,
    group_id:ManuallyDrop<Option<String>>,
    parent_batch:ManuallyDrop<Option<store::MemberStoreOwnedBatch>>,
    publication:ManuallyDrop<Option<PrivateChildPublicationGroup<M>>>,
    receipts:ManuallyDrop<Option<Box<MountedGroupMemberReceipts>>>,
    command:Option<MountedCommandEntry>,
    append:Option<CommandAppend>,
    output:ManuallyDrop<Option<MountedGroupReceiptOutput>>,
    record:ManuallyDrop<Option<CommandLogEntry>>,
    record_close_field:usize,
    displaced_shell_redo:ManuallyDrop<Vec<ShellHistoryReplay>>,
    phase:u8,
    captured_millis:i64,
    expires_at_us:u64,
    open_sequence:u64,
    context:Option<semio_framework_job::StepContextOwner>,
    closing:bool,
}

impl<M:SpaceMember+MemberFactory> MountedPrivateChildGroup<M> {
    fn new(captured_millis:i64,expires_at_us:u64)->Self{Self{identity:MountedChildGroupIdentityIssuer::new(),parent_issuer:MountedArtifactHandleIssuer::new(),parent_issuer_closed:false,parent_handle:None,parent_touched:false,group_id:ManuallyDrop::new(None),parent_batch:ManuallyDrop::new(None),publication:ManuallyDrop::new(None),receipts:ManuallyDrop::new(None),command:None,append:None,output:ManuallyDrop::new(None),record:ManuallyDrop::new(None),record_close_field:0,displaced_shell_redo:ManuallyDrop::new(Vec::new()),phase:0,captured_millis,expires_at_us,open_sequence:0,context:None,closing:false}}
    fn frame_birth_bytes()->usize{std::mem::size_of::<Self>()}
    fn next_close_byte_demand(&self)->Result<usize,semio_framework_value::ValueError>{
        if self.output.is_some(){return Ok(0);}
        if let Some(record)=self.record.as_ref(){return PagedCommandLog::record_demand(record,self.record_close_field);}
        if let Some(replay)=self.displaced_shell_redo.last(){return if replay.redo.action_id.capacity()!=0{Ok(replay.redo.action_id.capacity())}else if let Some(value)=replay.redo.args.as_ref(){PagedCommandLog::value_demand(value,0)}else{Ok(0)};}
        if self.displaced_shell_redo.capacity()!=0{return Ok(self.displaced_shell_redo.capacity()*std::mem::size_of::<ShellHistoryReplay>());}
        if let Some(append)=self.append.as_ref(){return Ok(append.next_close_byte_demand());}
        if let Some(command)=self.command.as_ref(){return Ok(command.next_close_byte_demand());}
        if let Some(receipts)=self.receipts.as_ref(){return if receipts.terminal_is_empty(){Ok(MountedGroupMemberReceipts::frame_birth_bytes())}else{receipts.next_close_byte_demand()};}
        if let Some(group)=self.publication.as_ref(){return group.next_close_byte_demand();}
        if let Some(context)=self.context.as_ref(){return Ok(context.next_close_byte_demand());}
        if let Some(batch)=self.parent_batch.as_ref(){let(capacity,release)=batch.next_demands()?;return Ok(capacity.max(release).max(batch.next_copy_byte_demand()));}
        if let Some(id)=self.group_id.as_ref(){return Ok(id.capacity());}
        if !self.identity.terminal_is_empty(){return Ok(self.identity.next_close_byte_demand());}
        Ok(0)
    }
    fn terminal_is_empty(&self)->bool{self.closing&&self.output.is_none()&&self.record.is_none()&&self.displaced_shell_redo.capacity()==0&&self.append.is_none()&&self.command.is_none()&&self.receipts.is_none()&&self.publication.is_none()&&self.context.is_none()&&self.parent_batch.is_none()&&self.group_id.is_none()&&self.identity.terminal_is_empty()&&self.parent_issuer_closed}
    fn close_step(&mut self,parent:&mut impl SpaceMember,registry:&mut ChildMemberRegistry<M>,graph:&mut store::CompositionGraph,live:&ChildContentView,grant:RetainedCloneGrant)->Result<semio_framework_value::retained_clone::RetainedCloneStep,Fault>{
        use semio_framework_value::retained_clone::{RetainedCloneProgress,RetainedCloneStep};
        if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}
        let bytes=self.next_close_byte_demand().map_err(|error|plugin_sdk_fault(error.to_string()))?;
        if grant.maximum_items==0||grant.maximum_release_bytes < bytes{return Ok(RetainedCloneStep::Progress(Default::default()));}
        self.closing=true;
        if self.output.is_some(){return Ok(self.receipts.as_mut().and_then(|receipts|receipts.final_receipt_mut()).expect("transferred output retains its exact empty receipt owner").retain_output(&mut self.output,grant));}
        if let Some(record)=self.record.as_mut(){if self.record_close_field==8{self.record.take();}else if PagedCommandLog::record_close_one(record,self.record_close_field){self.record_close_field+=1;}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
        if let Some(replay)=self.displaced_shell_redo.last_mut(){if replay.redo.action_id.capacity()!=0{drop(std::mem::take(&mut replay.redo.action_id));}else if let Some(value)=replay.redo.args.as_mut(){if matches!(value,DslValue::Null){replay.redo.args.take();}else{PagedCommandLog::value_close_one(value);}}else{self.displaced_shell_redo.pop();}return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
        if self.displaced_shell_redo.capacity()!=0{drop(std::mem::take(&mut*self.displaced_shell_redo));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
        if let Some(append)=self.append.as_mut(){let step=append.close_step(grant);self.append=None;return Ok(step);}
        if let Some(command)=self.command.as_mut(){let step=command.close_step(grant);if command.terminal_is_empty(){self.command=None;}return Ok(step);}
        if let Some(receipts)=self.receipts.as_mut(){if !receipts.terminal_is_empty(){return receipts.close_step(grant).map_err(|error|plugin_sdk_fault(error.to_string()));}drop(self.receipts.take());return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
        if let Some(group)=self.publication.as_mut(){let step=group.close_step(parent,registry,graph,live,grant)?;if group.terminal_is_empty(){self.publication.take();}return Ok(step);}
        if let Some(context)=self.context.as_mut(){let step=context.close_step(grant.maximum_items,grant.maximum_release_bytes);let progress=match step{semio_framework_job::InteractiveJobCloseStep::Pending{released_items,released_bytes}=>RetainedCloneProgress{copied_items:released_items,released_bytes,..Default::default()},semio_framework_job::InteractiveJobCloseStep::Blocked=>Default::default(),semio_framework_job::InteractiveJobCloseStep::Complete=>{self.context=None;RetainedCloneProgress{copied_items:1,..Default::default()}}};return Ok(RetainedCloneStep::Progress(progress));}
        if let Some(batch)=self.parent_batch.as_mut(){let step=batch.close_granted(grant).map_err(|error|plugin_sdk_fault(error.to_string()))?;if batch.terminal_is_empty(){self.parent_batch.take();}return Ok(step);}
        if self.group_id.is_some(){drop(self.group_id.take());return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}));}
        if !self.identity.terminal_is_empty(){return Ok(self.identity.close_granted(grant));}
        if !self.parent_issuer_closed{let step=self.parent_issuer.close_step(grant);self.parent_issuer_closed=true;return Ok(step);}
        Ok(RetainedCloneStep::Complete(Default::default()))
    }
}
impl<M:SpaceMember+MemberFactory> Drop for MountedPrivateChildGroup<M>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"mounted private child frame retains original inputs and staged owners until funded terminal close");}}

fn mounted_private_child_grant(capacity:usize,release:usize)->Result<RetainedCloneGrant,Fault>{if capacity>262_144||release>262_144{return Err(plugin_sdk_fault("mounted private publication exceeds its original physical admission"));}Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:64})}

impl<A:ArtifactApp,M:SpaceMember+MemberFactory+'static> VcsArtifactApp<A,M>{
    /// 🧪️ Borrows original completed-output ownership and refusal observations without widening production visibility.
    #[cfg(test)]
    pub(crate) fn test_original_owned_emit_observation(&self,operation:u64)->Option<(usize,usize,usize,bool,bool)>{
        let mounted=self.tool_operations.get(operation)?;
        let ArtifactToolCompletionValue::Emit(Ok(emit),_)=mounted.publication.as_ref()? else{return None;};
        Some((emit.artifact_mutations.len(),emit.owned_child_emits.len(),emit.owned_child_emits.as_ptr() as usize,mounted.terminal_fault.is_some(),mounted.cancellation_lease.as_ref()?.token.is_cancelled_now()))
    }

    async fn mount_original_emit_publication(&mut self,verb:&str,emit:Emit<A::Mutation,A::ConfigMutation,A::DraftMutation>,meta:&ActionMeta,authority:Option<(semio_framework_job::Operation,ToolCancellationLease)>)->Result<InvocationResult,Fault>{
        self.mount_original_reserved_owners(verb,Some(ArtifactToolCompletionValue::Emit(Ok(emit),EphemeralEmit::default())),None,None,meta,authority).await
    }

    /// 🎒️ Installs original reserved producer and completion owners before fallible publication capture.
    async fn mount_original_reserved_owners(&mut self,verb:&str,publication:Option<ArtifactToolCompletionValue<A>>,reserved_producer:Option<ArtifactReservedToolJob>,completion:Option<ArtifactToolCompletion<A>>,meta:&ActionMeta,authority:Option<(semio_framework_job::Operation,ToolCancellationLease)>)->Result<InvocationResult,Fault>{
        let revision=self.store.content_revision_now();
        let generation=semio_framework_job::Generation(self.store.generation_now());
        let base_revision=semio_framework_job::RevisionId(u64::from_be_bytes(revision[..8].try_into().unwrap()));
        let(operation,lease)=match authority{Some(authority)=>authority,None=>{let operation_id=self.admit_typed_operation_slot().ok_or_else(||plugin_sdk_fault("every fixed publication slot already retains an original operation"))?;let operation=semio_framework_job::Operation::new(operation_id,base_revision,generation,operation_id.0);let lease=self.tool_cancellations.begin_keyed(ToolOperationKey{app_instance_id:meta.instance_id,document:ArtifactDocumentAuthority(meta.instance_id),operation_id,base_revision,generation})?;(operation,lease)}};
        let operation_id=operation.operation.0;
        let reservation=self.typed_operation_reservations[operation_id as usize % ARTIFACT_LIVE_OUTPUT_SLOTS];
        if !self.tool_operations.can_insert(operation_id)||reservation.is_some_and(|owner|owner!=operation_id){return Err(plugin_sdk_fault("original emission lost its exact pre-admitted publication slot"));}
        let mounted=MountedTypedCommandFullOperation::<A>{
            verb:verb.into(),meta:meta.clone(),operation,canonical_revision:revision,artifact_generation:generation.0,
            config_generation:self.config_store.generation_now(),draft_generation:self.draft_store.generation_now(),presence_generation:0,transient_generation:0,
            window_config_authority:None,window_transient_authority:None,publication_lanes:&[],
            session:None,session_rejected:None,reserved_producer,completion,raw_input:None,output_chunks:None,cancellation_lease:Some(lease),terminal_outcome:None,terminal_seen:true,
            publication,pending_artifact_publication:None,pending_child_publication:None,
            owned_child_group:None,owned_child_committed:false,owned_child_result_pending:false,
            captured_child_content:Some(std::sync::Arc::new(ChildContentView::clone(&self.child_content_root))),captured_child_content_generation:self.child_content_generation,
            result_page:None,result_page_presented:false,result_sequence:0,publication_progress:0,publication_checkpoint:None,publication_attempt:0,
            ui_pending:true,progress:None,progress_pending:false,user_cancel_requested:false,published_artifact:false,published_config:false,published_window_config:false,
            command_logged:false,interaction_revalidated:false,terminal_fault:None,stage:MountedTypedCommandFullOperationStage::Publishing,
        };
        self.tool_operations.insert_admitted(operation_id,mounted);
        self.release_reserved_emit_slot(operation_id);
        let capture:Result<_,Fault>=async{
            if self.live_runtime_instance_id!=Some(meta.instance_id){return Err(plugin_sdk_fault("original emission does not belong to its mounted live app instance"));}
            let proof=self.qualified_tool_proof(verb)?;
            let window_config=self.window_config_store.capture(meta.view_state.as_ref()).await?;
            let window_transient=self.window_transient_store.capture(meta.view_state.as_ref())?;
            Ok((proof.publication_lanes(),window_config,window_transient,self.presence_store.generation().await,self.transient_store.generation().await))
        }.await;
        let mounted=self.tool_operations.get_mut(operation_id).expect("original completed output remains in its exact admitted slot");
        match capture{
            Ok((lanes,window_config,window_transient,presence,transient))=>{
                mounted.publication_lanes=lanes;mounted.window_config_authority=window_config;mounted.window_transient_authority=window_transient;
                mounted.presence_generation=presence;mounted.transient_generation=transient;
                if let Some(ArtifactToolCompletionValue::Emit(Ok(emit),_))=mounted.publication.as_mut(){let inline=take_inline_interaction_verbs(&mut emit.effects);if !inline.is_empty(){self.typed_inline_interaction_verbs.push((operation_id,inline));}}
            }
            Err(fault)=>{mounted.terminal_fault.get_or_insert_with(||ArtifactBoundedToolFault::from_fault(&fault));mounted.cancellation_lease.as_ref().expect("original keyed lease remains retained").cancel();}
        }
        let mut result=Self::empty_result(verb,meta,Vec::new(),Vec::new(),UiDirtyScope::None).await;
        result.output=DslValue::Object(vec![("operationId".into(),DslValue::String(operation_id.to_string())),("generation".into(),DslValue::String(operation.generation.0.to_string()))]);
        Ok(result)
    }

    fn advance_private_child_group(&mut self,mounted:&mut MountedTypedCommandFullOperation<A>)->Result<semio_framework_value::retained_clone::RetainedCloneStep,Fault>{
        use semio_framework_value::retained_clone::{RetainedCloneProgress,RetainedCloneStep};
        let step=(||->Result<RetainedCloneStep,Fault>{
        let operation=mounted.operation.operation.0;
        let kind=self.declared_dispatch_kind(&mounted.verb).unwrap_or(ActionKind::Mutation);
        let owner=self.private_child_groups.get_mut(operation).ok_or_else(||plugin_sdk_fault("mounted publication lost its original admitted group frame"))?;
        if owner.closing{return Err(plugin_sdk_fault("mounted private publication requires bounded retirement after cancellation"));}
        if owner.phase>=9{return Ok(RetainedCloneStep::Complete(Default::default()));}
        let structural=||RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()});
        let error=|error:semio_framework_value::ValueError|plugin_sdk_fault(error.to_string());
        if owner.phase==0{
            if owner.identity.ready(){*owner.group_id=owner.identity.take_ready(mounted_private_child_grant(0,0)?);owner.phase=1;return Ok(structural());}
            let source=MountedChildGroupIdentitySource{parent:&self.store.envelope().id,actor:&mounted.meta.actor,revision:mounted.canonical_revision,instance:mounted.meta.instance_id,operation};
            return owner.identity.advance(source,mounted_private_child_grant(owner.identity.next_capacity_byte_demand(),0)?).map_err(error);
