    fn inverse(&self, base: &SurfaceSnapshot) -> Self {
        Self { count: self.count.map(|_| base.count) }
    }
    fn between(base: &SurfaceSnapshot, other: &SurfaceSnapshot) -> Self {
        Self { count: (base.count != other.count).then_some(other.count) }
    }
